const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const country = ee.FeatureCollection('USDOS/LSIB_SIMPLE/2017').filter(ee.Filter.eq('country_na', 'Denmark'));
  const geometry = country.geometry();

  const date2017 = '2017-07-19';
  const date2018 = '2018-07-24';
  const dateRange = 2; // Use a +/- 2 day window to increase chance of finding a clear image

  const start2017 = ee.Date(date2017).advance(-dateRange, 'day');
  const end2017 = ee.Date(date2017).advance(dateRange, 'day');

  const start2018 = ee.Date(date2018).advance(-dateRange, 'day');
  const end2018 = ee.Date(date2018).advance(dateRange, 'day');

  // Function to calculate NDVI and mask clouds using SCL band for Sentinel-2
  function processS2(image) {
    // Keep vegetation (4), not vegetated (5), and soil (6)
    const scl = image.select('SCL');
    const mask = scl.eq(4).or(scl.eq(5)).or(scl.eq(6));
    const ndvi = image.normalizedDifference(['B8', 'B4']).rename('NDVI');
    return image.addBands(ndvi).updateMask(mask);
  }

  // 2. Data Acquisition & Check
  const s2Collection = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(geometry);

  const col2017 = s2Collection.filterDate(start2017, end2017);
  const col2018 = s2Collection.filterDate(start2018, end2018);

  const col2017Size = col2017.size().getInfo();
  const col2018Size = col2018.size().getInfo();

  if (col2017Size === 0 || col2018Size === 0) {
    console.log(`Image count 2017: ${col2017Size}`);
    console.log(`Image count 2018: ${col2018Size}`);
    console.log("No images found for one or both dates. Try widening the date range.");
    console.log("A"); // C1
    return;
  }

  // 3. Processing
  const image2017 = col2017.map(processS2).median().clip(geometry);
  const image2018 = col2018.map(processS2).median().clip(geometry);

  // 4. Calculation & Validation of Pixel Counts
  const scale = 3000;
  const commonReducer = ee.Reducer.mean().combine({
    reducer2: ee.Reducer.count(),
    sharedInputs: true
  });

  const stats2017 = image2017.select('NDVI').reduceRegion({
    reducer: commonReducer,
    geometry: geometry,
    scale: scale,
    maxPixels: 1e10
  });

  const stats2018 = image2018.select('NDVI').reduceRegion({
    reducer: commonReducer,
    geometry: geometry,
    scale: scale,
    maxPixels: 1e10
  });

  const results = ee.Dictionary({
    '2017': stats2017,
    '2018': stats2018
  }).getInfo();

  const ndvi2017 = results['2017']['NDVI_mean'];
  const count2017 = results['2017']['NDVI_count'];
  const ndvi2018 = results['2018']['NDVI_mean'];
  const count2018 = results['2018']['NDVI_count'];

  if (count2017 === 0 || count2018 === 0) {
    console.log(`Valid pixel count 2017: ${count2017}`);
    console.log(`Valid pixel count 2018: ${count2018}`);
    console.log("No valid pixels after cloud masking. Area likely fully clouded.");
    console.log("B"); // C2
    return;
  }

  if (ndvi2017 === null || ndvi2018 === null) {
    console.log(`NDVI 2017: ${ndvi2017}`);
    console.log(`NDVI 2018: ${ndvi2018}`);
    console.log("Calculation failed, result is null.");
    console.log("B"); // C3
    return;
  }

  // 5. Validation & Final Answer
  // "More brown" means less green vegetation, which corresponds to a lower NDVI value.
  console.log(`Denmark Average NDVI (July 2017): ${ndvi2017.toFixed(4)}`);
  console.log(`Denmark Average NDVI (July 2018): ${ndvi2018.toFixed(4)}`);
  console.log(`Valid pixel count 2017: ${count2017}`);
  console.log(`Valid pixel count 2018: ${count2018}`);

  if (ndvi2018 < ndvi2017) {
    console.log("NDVI in 2018 was lower than in 2017, indicating less healthy/green vegetation.");
    console.log("A");
  } else {
    console.log("NDVI in 2018 was not lower than in 2017.");
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(e => {
  console.error(e);
  console.log("D");
});
